final readonly class SiteMutationService{public function __construct(private PDO $pdo,private SiteRepository $sites,private ?AuditLoggerInterface $audit=null){}public function create(array $input,int $actorId,string $email):Site{$d=$this->normalise($input,true);$started=!$this->pdo->inTransaction();if($started)$this->pdo->beginTransaction();try{$id=$this->sites->create($d['code'],$d['name'],$d['host'],$d['homepage_slug'],$d['theme_code'],$d['locale'],$d['currency'],$d['base_url'],$d['website_code'],$d['store_code'],$d['store_view_code'],$d['path_prefix']);if($started)$this->pdo->commit();}catch(Throwable $e){if($started&&$this->pdo->inTransaction())$this->pdo->rollBack();throw new RuntimeException('Site creation failed and was rolled back.',previous:$e);} $site=$this->sites->findById($id);if($site===null)throw new RuntimeException('Created Site could not be reloaded.');$this->audit?->logAction($actorId,$email,'site.created','site',(string)$id,'Created Site.',['code'=>$site->code,'host'=>$d['host']]);return$site;}public function update(Site $site,array $input,int $actorId,string $email):Site{$d=$this->normalise($input,false,$site);$this->sites->update($site->id,$d['code'],$d['name'],$d['status'],$d['homepage_slug'],$d['theme_code'],$d['locale'],$d['currency'],$d['base_url'],$d['website_code'],$d['store_code'],$d['store_view_code'],$d['path_prefix']);$saved=$this->sites->findById($site->id);if($saved===null)throw new RuntimeException('Updated Site could not be reloaded.');$this->audit?->logAction($actorId,$email,'site.updated','site',(string)$site->id,'Updated Site.',['code'=>$saved->code]);return$saved;}private function normalise(array $i,bool $create,?Site $s=null):array{$required=static function(array $a,string $k,string $m):string{$v=trim((string)($a[$k]??''));if($v==='')throw new RuntimeException($m);return$v;};$slug=static function(string $v,string $field):string{if(!preg_match('/^[a-z0-9][a-z0-9_-]*$/i',$v))throw new RuntimeException('Invalid '.str_replace('_',' ',$field).'. Use letters, numbers, underscore or dash.');return$v;};$opt=static fn(array $a,string $k,string $d):string=>trim((string)($a[$k]??''))?:$d;$code=$slug($required($i,'code','Site code is required.'),'code');$name=$required($i,'name','Site name is required.');$host=$create?strtolower($required($i,'host','Primary host is required.')):'';if($create&&!preg_match('/^[a-z0-9.-]+$/',$host))throw new RuntimeException('Invalid host.');$path=trim((string)($i['path_prefix']??$s?->pathPrefix??''));return['code'=>$code,'name'=>$name,'host'=>$host,'status'=>in_array((string)($i['status']??$s?->status??'active'),['active','inactive'],true)?(string)($i['status']??$s?->status??'active'):'inactive','homepage_slug'=>$slug($opt($i,'homepage_slug',$s?->homepageSlug??'home'),'homepage_slug'),'theme_code'=>$slug($opt($i,'theme_code',$s?->themeCode??'default'),'theme_code'),'locale'=>$opt($i,'locale',$s?->locale??'en_AU'),'currency'=>$opt($i,'currency',$s?->currency??'AUD'),'base_url'=>$opt($i,'base_url',$s?->baseUrl??''),'website_code'=>$slug($opt($i,'website_code',$s?->websiteCode??'main'),'website_code'),'store_code'=>$slug($opt($i,'store_code',$s?->storeCode??'main'),'store_code'),'store_view_code'=>$slug($opt($i,'store_view_code',$s?->storeViewCode??'default'),'store_view_code'),'path_prefix'=>$path===''?'':'/'.trim($path,'/')];}}










